const fs = require('fs');
const path = require('path');

const katolikQuestions = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'generators', 'agama_katolik.json'), 'utf8'));

const g1to4 = katolikQuestions.filter(q => q.grade >= 1 && q.grade <= 4);
const seenQuestions = new Set(g1to4.map(q => q.question));
const finalQuestions = [...g1to4];

function addQ(grade, difficulty, topic, question, options, correctAnswer, explanation) {
  if (seenQuestions.has(question)) {
    throw new Error(`Duplicate Katolik question found: "${question}"`);
  }
  seenQuestions.add(question);

  const diffCode = difficulty === 'mudah' ? 'm' : (difficulty === 'sedang' ? 's' : 'u');
  const index = finalQuestions.filter(q => q.grade === grade && q.difficulty === difficulty).length + 1;
  const id = `aga-katolik-k${grade}-${diffCode}${String(index).padStart(2, '0')}`;

  finalQuestions.push({
    id,
    grade,
    subject: 'pendidikan-agama',
    religion: 'katolik',
    difficulty,
    topic,
    question,
    options,
    correctAnswer,
    explanation
  });
}

addQ(5, 'mudah', 'Tujuh Sakramen', 'Jumlah seluruh sakramen yang diakui dan dirayakan dalam Gereja Katolik berjumlah ... sakramen.', ['5', '6', '7', '10'], 2, 'Gereja Katolik memiliki 7 sakramen: Baptis, Krisma, Ekaristi, Tobat, Pengurapan Orang Sakit, Imamat, dan Perkawinan.');
addQ(5, 'mudah', 'Sakramen Inisiasi', 'Tiga sakramen yang termasuk ke dalam kelompok Sakramen Inisiasi Katolik adalah Sakramen Baptis, Krisma, dan ...', ['Imamat', 'Ekaristi', 'Tobat', 'Minyak Suci'], 1, 'Tiga sakramen inisiasi dasar kristiani adalah Baptis, Krisma (Penguatan), dan Ekaristi.');
addQ(5, 'mudah', 'Sakramen Krisma', 'Sakramen Krisma (Penguatan) diterimakan untuk mencurahkan Roh Kudus secara penuh guna menjadikan orang beriman menjadi ...', ['Malaikat di surga', 'Saksi Kristus yang dewasa dalam iman dan berani mewartakan Injil', 'Imam di biara', 'Penguasa politik'], 1, 'Sakramen Penguatan menyempurnakan rahmat baptis dan memperlengkapi umat menjadi saksi Kristus yang dewasa.');
addQ(5, 'mudah', 'Bunda Teresa Kalkuta', 'Santa pelindung kaum miskin dan telantar yang melayani orang-orang yang sekarat di Kalkuta India adalah Santa ...', ['Klara dari Asisi', 'Teresa dari Kalkuta', 'Bernadette', 'Theresia Lisieux'], 1, 'Bunda Teresa dari Kalkuta mendedikasikan hidupnya merawat kaum termiskin dari yang miskin dengan cinta kasih Kristus.');
addQ(5, 'mudah', 'Beato Carlo Acutis', 'Remaja kudus pencinta Ekaristi di era internet yang membuat situs web pameran mukjizat Ekaristi sedunia bernama Beato ...', ['Dominikus Savio', 'Carlo Acutis', 'Tarsisius', 'Aloysius Gonzaga'], 1, 'Beato Carlo Acutis adalah rasul siber Ekaristi bagi generasi muda Katolik modern.');
addQ(5, 'mudah', 'Motto AMDG', 'Semboyan rohani Santo Ignatius Loyola pendiri Serikat Yesus (Yesuit) berbunyi "Ad Maiorem Dei Gloriam" (AMDG), yang artinya ...', ['"Hanya untuk kesenangan manusia"', '"Demi Lebih Besarnya Kemuliaan Allah"', '"Kemenangan para prajurit perang"', '"Kekayaan harta duniawi"'], 1, 'AMDG adalah semboyan pengabdian segenap daya hidup demi kemuliaan Allah yang lebih besar.');
addQ(5, 'mudah', 'Gereja Perdana', 'Kitab Suci Perjanjian Baru yang memuat kisah persekutuan dan penyebaran iman jemaat Gereja perdana adalah Kitab ...', ['Kisah Para Rasul', 'Wahyu', 'Surat Ibrani', 'Kejadian'], 0, 'Kisah Para Rasul (Acta Apostolorum) mencatat karya Roh Kudus dalam kelahiran dan misi Gereja perdana.');
addQ(5, 'mudah', 'Empat Peristiwa Rosario', 'Empat kelompok peristiwa dalam Doa Rosario adalah Peristiwa Sukacita, Peristiwa Sedih, Peristiwa Mulia, dan Peristiwa ...', ['Kemenangan', 'Terang', 'Pengharapan', 'Penyembuhan'], 1, 'Empat rangkaian peristiwa Rosario: Sukacita, Terang (Luminous), Sedih, dan Mulia.');
addQ(5, 'mudah', 'Sakramen Penyembuhan', 'Dua sakramen yang digolongkan sebagai Sakramen Penyembuhan dalam Gereja Katolik adalah Sakramen Tobat dan Sakramen ...', ['Pengurapan Orang Sakit', 'Krisma', 'Baptis', 'Imamat'], 0, 'Sakramen Penyembuhan memulihkan jiwa (Tobat) dan raga batin (Pengurapan Orang Sakit).');
addQ(5, 'mudah', 'Sakramen Panggilan', 'Dua sakramen yang digolongkan sebagai Sakramen Pelayanan Persekutuan dan Perutusan (Panggilan Hidup) adalah Sakramen Imamat dan Sakramen ...', ['Ekaristi', 'Perkawinan', 'Krisma', 'Baptis'], 1, 'Sakramen Imamat dan Perkawinan menguduskan panggilan hidup untuk melayani persekutuan umat Allah.');

addQ(5, 'sedang', 'Empat Pilar Gereja Perdana', 'Berdasarkan Kisah Para Rasul 2:42, empat tiang pokok persekutuan Gereja perdana di Yerusalem adalah bertekun dalam pengajaran para rasul, persekutuan, doa, dan ...', ['Latihan memanah', 'Pemecahan roti (Perjamuan Ekaristi)', 'Perdagangan kain sutera', 'Pembangunan gedung istana'], 1, 'Kisah Para Rasul 2:42: jemaat bertekun dalam ajaran rasul, koinonia (persekutuan), pemecahan roti, dan doa.');
addQ(5, 'sedang', 'Pelayan Sakramen Krisma', 'Pelayan biasa (utama) yang memiliki wewenang menerimakan Sakramen Krisma (Penguatan) kepada umat beriman adalah ...', ['Diakon', 'Bapak Uskup', 'Frater', 'Suster'], 1, 'Uskup sebagai penerus para rasul adalah pelayan utama sakramen Krisma.');
addQ(5, 'sedang', 'Pengurapan Minyak Krisma', 'Saat menerimakan Sakramen Krisma, bapak uskup mengurapi dahi calon krisma dengan Minyak Krisma membentuk tanda salib sambil bersabda: ...', ['"Jadilah kaya raya di dunia"', '"Semoga engkau dimeteraikan oleh karunia Roh Kudus"', '"Pergilah berlayar ke negeri seberang"', '"Engkau telah bebas dari seluruh kewajiban gereja"'], 1, 'Formula sakramen Krisma: "Accipe signaculum doni Spiritus Sancti" (Semoga engkau dimeteraikan oleh karunia Roh Kudus).');
addQ(5, 'sedang', 'Kongregasi Bunda Teresa', 'Kongregasi suster biarawati yang didirikan oleh Santa Teresa dari Kalkuta untuk merawat orang-orang sekarat dan terlantar dinamakan ...', ['Ordo Fransiskan', 'Misionaris Cinta Kasih (Missionaries of Charity)', 'Suster Ursulin', 'Karmelit Tak Berkasut'], 1, 'Missionaries of Charity dikenal dengan jubah sari putih bergaris biru melayani kaum termiskin.');
addQ(5, 'sedang', 'Kemiskinan Santo Fransiskus', 'Tindakan radikal Santo Fransiskus dari Asisi saat memutuskan mengikuti Kristus adalah melepaskan seluruh pakaian mewahnya di hadapan uskup untuk hidup memeluk ...', ['Kemewahan istana raja', 'Ibu Kemiskinan suci melayani kaum kusta dan miskin', 'Karier prajurit berkuda', 'Bisnis kain ayahnya'], 1, 'Santo Fransiskus melepaskan warisan duniawi demi hidup bebas mencintai Tuhan dalam kemiskinan sukarela.');
addQ(5, 'sedang', 'Tujuh Karunia Roh Kudus', 'Jumlah Karunia Roh Kudus yang dicurahkan dalam Sakramen Penguatan untuk membimbing budi dan kehendak manusia berjumlah ... karunia.', ['3', '5', '7', '12'], 2, 'Tujuh Karunia Roh Kudus (Yesaya 11:2): Kebijaksanaan, Pengertian, Nasihat, Keperkasaan, Pengenalan, Kesalehan, dan Takut akan Tuhan.');
addQ(5, 'sedang', 'Peristiwa Terang Yohanes Paulus II', 'Misteri Peristiwa Terang dalam Doa Rosario yang memuat peristiwa Pembaptisan Yesus hingga Perjamuan Terakhir ditetapkan pada tahun 2002 oleh Paus ...', ['Yohanes XXIII', 'Yohanes Paulus II', 'Benediktus XVI', 'Fransiskus'], 1, 'Paus Yohanes Paulus II menambahkan Peristiwa Terang (Mysteria Lucis) melalui surat apostolik Rosarium Virginis Mariae.');
addQ(5, 'sedang', 'Buah Roh Takut Akan Allah', 'Seorang murid katolik yang memiliki karunia Roh Kudus "takut akan Tuhan" akan bersikap ...', ['Takut bertemu dengan bapak imam', 'Takut berbuat dosa karena sangat mencintai Allah dan menjunjung tinggi kejujuran di mana pun berada', 'Menghindari membaca Alkitab', 'Takut keluar rumah saat malam hari'], 1, 'Karunia takut akan Tuhan (filial fear) bukan rasa ngeri, melainkan rasa hormat penuh cinta yang tidak ingin melukai hati Allah.');
addQ(5, 'sedang', 'Dokumen Nostra Aetate Konsili', 'Dokumen Konsili Vatikan II "Nostra Aetate" mengajarkan sikap Gereja Katolik terhadap agama-agama non-kristen yaitu ...', ['Menolak dan mengutuk semua pemeluk agama lain', 'Menghormati segala hal yang benar dan suci dalam agama-agama lain serta memajukan dialog dan kerja sama persaudaraan', 'Memaksa semua orang menjadi Katolik', 'Menutup pintu gereja bagi masyarakat umum'], 1, 'Nostra Aetate menegaskan Gereja menghargai nilai moral dan spiritual dalam agama lain seraya memajukan dialog damai.');
addQ(5, 'sedang', 'Sifat Sakramen Perkawinan', 'Dua sifat hakiki dari Sakramen Perkawinan dalam Gereja Katolik adalah bersifat Monogam (satu pria dengan satu wanita) dan ...', ['Boleh bercerai jika bosan', 'Tak terceraikan seumur hidup hingga maut memisahkan', 'Hanya berlaku selama lima tahun', 'Dapat diperjualbelikan'], 1, 'Perkawinan katolik bersifat satu untuk selamanya: "Apa yang telah dipersatukan Allah, tidak boleh diceraikan manusia".');
addQ(5, 'sedang', 'Memelihara Kesucian Pergaulan', 'Menjauhkan diri dari tontonan pornografi, pergaulan bebas, dan perkataan kotor di internet merupakan wujud ketaatan pada Perintah Allah ke- ...', ['Ke-4 dan ke-5', 'Ke-6 (Jangan berzinah) dan ke-9 (Jangan mengingini istri sesamamu)', 'Ke-7 dan ke-8', 'Ke-1 dan ke-2'], 1, 'Perintah ke-6 dan ke-9 memurnikan kekudusan tubuh, pikiran, dan hati dalam pergaulan yang sehat.');
addQ(5, 'sedang', 'Karya Karitatif Paroki', 'Kegiatan seksi sosial karitatif di paroki yang membagikan paket beras sembako kepada warga sekitar gereja tanpa memandang agama mencerminkan wajah Gereja yang ...', ['Mencari popularitas politik lokal', 'Hadir sebagai persekutuan yang berbelas kasih dan peduli pada kaum dhuafa', 'Memamerkan kelebihan uang kas paroki', 'Menghabiskan anggaran tahunan'], 1, 'Karya karitatif adalah perwujudan iman nyata yang melayani sesama dengan belas kasih Kristus.');
addQ(5, 'sedang', 'Kata Mutiara Carlo Acutis', 'Beato Carlo Acutis memiliki ungkapan termasyhur tentang Ekaristi yang berbunyi: "Ekaristi adalah ..."', ['Beban hidup anak muda', 'Jalan tol saya menuju surga', 'Tradisi makan roti gandum', 'Pelajaran sejarah kuno'], 1, 'Carlo Acutis memandang Ekaristi harian sebagai jalan tol (highway to heaven) menuju kekudusan hidup.');
addQ(5, 'sedang', 'Pesan Belas Kasih Bunda Teresa', 'Santa Teresa dari Kalkuta berpesan: "Jika engkau tidak dapat memberi makan seratus orang, berilah makan ..."', ['Dua ratus orang sekaligus', 'Satu orang saja', 'Para pejabat istana', 'Hewan peliharaanmu saja'], 1, 'Bunda Teresa mengajarkan untuk mulai melakukan perbuatan kasih dari hal kecil kepada satu pribadi di depan kita.');
addQ(5, 'sedang', 'Tugas Pelayanan Diakon', 'Tiga jenjang tahbisan dalam Sakramen Imamat adalah Uskup, Imam, dan Diakon. Tugas pokok seorang diakon tertahbis adalah ...', ['Memimpin Misa kudus sendirian', 'Melayani altar, mewartakan Injil, membaptis, memimpin upacara pernikahan/pemakaman, dan karya amal kasih', 'Menggantikan tugas bapa Paus di Roma', 'Menghakimi perselisihan hukum negara'], 1, 'Diakonat adalah tahbisan pertama yang dikhususkan untuk pelayanan sabda, liturgi, dan karya karitatif kemanusiaan.');
addQ(5, 'sedang', 'Gereja Tubuh Mistik Kristus', 'Dalam Surat 1 Korintus 12, Santo Paulus mengajarkan bahwa Gereja adalah Tubuh Mistik Kristus. Hubungan antara Kristus dan Gereja adalah ...', ['Gereja adalah atap dan Kristus adalah lantainya', 'Kristus adalah Kepala Gereja dan umat beriman adalah anggota-anggota tubuh-Nya', 'Gereja tidak membutuhkan Kristus', 'Umat beriman adalah penguasa atas Kristus'], 1, 'Kristus adalah Kepala dari Tubuh yaitu Gereja; setiap orang beriman adalah anggota yang saling terhubung.');
addQ(5, 'sedang', 'Pertobatan Ignatius Loyola', 'Peristiwa yang menjadi titik balik pertobatan Santo Ignatius Loyola dari seorang ksatria ambisius menjadi abdi Kristus adalah saat ...', ['Menemukan peti harta karun emas', 'Kaki terluka parah terkena peluru meriam di benteng Pamplona dan membaca buku riwayat hidup Yesus serta para kudus', 'Terpilih menjadi jenderal perang raja Spanyol', 'Tersesat di padang gurun pasir'], 1, 'Masa pemulihan luka tembak di Pamplona membuka mata hati Ignatius membaca riwayat para orang kudus dan berbalik mengabdi Kristus.');
addQ(5, 'sedang', 'Gereja dan Inkulturasi', 'Gereja Katolik menyambut baik seni gamelan Jawa, tarian Manggarai, atau ukiran Asmat dalam liturgi suci selama hal tersebut ...', ['Menaikkan tarif tiket masuk gereja', 'Selaras dengan kemurnian iman rasuli dan memperdalam rasa hormat sembah sujud kepada Allah yang Mahasuci', 'Menggantikan teks doa Bapa Kami', 'Menghilangkan patung Salib Yesus'], 1, 'Inkulturasi yang sejati mengangkat kekayaan budaya luhur untuk memuliakan Allah tanpa mengorbankan iman.');
addQ(5, 'sedang', 'Membela Sahabat Dari Fitnah Online', 'Ketika ada teman sekelas difitnah dengan foto editan di grup WhatsApp sekolah, tindakan seorang anak katolik yang berani membela kebenaran adalah ...', ['Ikut menertawakan dan membagikan foto tersebut ke grup lain', 'Mengklarifikasi fakta dengan tegas bahwa foto itu fitnah, membela kehormatan kawan, dan melapor ke wali kelas', 'Menghapus aplikasi WhatsApp dan pura-pura tuli', 'Menyuruh kawan tersebut pindah ke sekolah lain'], 1, 'Membela korban fitnah adalah pelaksanaan nyata kebajikan menegakkan kebenaran dan keadilan.');
addQ(5, 'sedang', 'Makna Sakramen Pengurapan Sakit', 'Sakramen Pengurapan Orang Sakit menggunakan Minyak Suci (Oleum Infirmorum) yang diurapkan pada dahi dan tangan bertujuan untuk ...', ['Membuat orang sakit cepat meninggal dunia', 'Menganugerahkan rahmat penghiburan, kekuatan rohani, pengampunan dosa, dan pemulihan kesehatan jiwa raga bagi orang yang menderita sakit berat', 'Menggantikan tugas pengobatan medis dokter rumah sakit', 'Menjauhkan dokter dari kamar pasien'], 1, 'Sakramen Pengurapan menguatkan orang sakit dengan rahmat damai Kristus dan pengampunan dosa.');

addQ(5, 'sulit', 'Teologi Milik Bersama Gereja Perdana', 'Dalam Kisah Para Rasul 2:44-45 dicatat: "Semua orang yang telah menjadi percaya tetap bersatu, dan segala kepunyaan mereka adalah kepunyaan bersama...". Apakah Gereja perdana mengajarkan penghapusan hak milik secara paksa?', ['Ya, para rasul menyita paksa semua tanah warga Yerusalem', 'Bukan pemaksaan komunisme, melainkan kerelaan kasih persaudaraan yang begitu meluap sehingga mereka secara sukarela menjual harta berlebih demi memastikan tidak ada seorang pun saudara seiman yang berkekurangan pangan', 'Jemaat dilarang memiliki rumah pribadi', 'Hanya peraturan bagi para janda lanjut usia'], 1, 'Milik bersama Gereja perdana berakar pada kedermawanan sukarela (koinonia) yang digerakkan oleh kasih Roh Kudus tanpa paksaan.');
addQ(5, 'sulit', 'Perbedaan Karunia Roh vs Buah Roh', 'Katekismus membedakan 7 Karunia Roh Kudus (Yesaya 11) dan 9 Buah Roh Kudus (Galatia 5). Perbedaan hakiki antara keduanya adalah ...', ['Karunia Roh hanya untuk para imam, buah Roh untuk orang miskin', 'Karunia Roh adalah perlengkapan anugerah ilahi cuma-cuma yang memampukan budi dan kehendak merespons dorongan Roh Kudus, sedangkan Buah Roh adalah hasil kematangan moral karakter hidup yang nyata dari orang yang dipimpin Roh', 'Karunia Roh berupa uang tunai, buah Roh berupa buah apel', 'Keduanya tidak memiliki perbedaan apa pun'], 1, 'Karunia Roh memperlengkapi jiwa dari dalam (disposisi batin), sedangkan Buah Roh adalah hasil kebajikan moral yang tampak keluar.');
addQ(5, 'sulit', 'Paradoks Nostra Aetate Dialog dan Pewartaan', 'Bagaimana Gereja Katolik menyeimbangkan sikap menghormati nilai-nilai suci dalam agama-agama lain (Nostra Aetate) dengan kewajiban mewartakan Injil Kristus?', ['Gereja Katolik melarang anggotanya berbicara tentang Yesus kepada orang lain', 'Gereja menghormati martabat dan benih kebenaran (semina Verbi) pada sesama warga tanpa kompromi, seraya tetap dengan setia mewartakan Kristus sebagai kepenuhan Jalan, Kebenaran, dan Hidup', 'Gereja menganggap semua agama memiliki kebenaran yang sama persis tanpa perbedaan', 'Gereja menutup seluruh karya misi pewartaan'], 1, 'Dialog dan pewartaan (dialogue and proclamation) berjalan seiring: saling menghargai tanpa kehilangan identitas iman pada Kristus.');
addQ(5, 'sulit', 'Sifat Tak Terceraikan Sakramen Perkawinan', 'Yesus bersabda tentang perkawinan: "Demikianlah mereka bukan lagi dua, melainkan satu. Karena itu, apa yang telah dipersatukan Allah, tidak boleh diceraikan manusia" (Matius 19:6). Dasar teologis sifat tak terceraikan (indissolubilitas) ini adalah ...', ['Pemerintah melarang perceraian di pengadilan negeri', 'Perkawinan sakramental katolik adalah gambaran nyata dari ikatan perjanjian kasih setia Kristus dengan Gereja-Nya yang abadi dan tak pernah mengingkari janji', 'Biaya pengurusan surat cerai terlalu mahal', 'Hanya tradisi adat suku Yahudi'], 1, 'Perkawinan katolik memantulkan kesetiaan mutlak Kristus kepada Mempelai-Nya (Gereja) yang tidak pernah terceraikan.');
addQ(5, 'sulit', 'Filosofi Kemiskinan Sukarela Fransiskus Asisi', 'Mengapa Santo Fransiskus dari Asisi memandang kemiskinan sukarela bukan sebagai penderitaan yang memalukan, melainkan sebagai "Ibu Kemiskinan" yang memerdekakan?', ['Karena Fransiskus malas bekerja mencari uang', 'Dengan menanggalkan ikatan ketamakan harta materi duniawi, jiwanya menjadi bebas murni untuk bergantung seutuhnya kepada Allah dan mencintai sesama tanpa sekat egoisme', 'Karena Fransiskus ingin mendapat pujian dari Paus Roma', 'Supaya ia tidak perlu membayar pajak kepada raja'], 1, 'Kemiskinan sukarela (kenosis) membebaskan manusia dari perbudakan materi dan membuka ruang hati bagi kekayaan hadirat Allah.');
addQ(5, 'sulit', 'Kemartiran Diakon Santo Laurensius', 'Ketika penguasa Roma menuntut Santo Laurensius menyerahkan "harta kekayaan Gereja", Laurensius mengumpulkan kaum miskin, yatim piatu, dan orang buta lalu berkata: "Inilah harta Gereja yang kekal". Nilai teologis dari tindakan Laurensius adalah ...', ['Laurensius menyembunyikan emas di bawah tanah', 'Orang-orang miskin dan menderita adalah harta sejati Gereja Kristus yang paling berharga, bukan emas perak materi duniawi', 'Laurensius ingin mempermainkan hakim pengadilan Romawi', 'Kaum miskin memiliki tabungan uang yang banyak'], 1, 'Santo Laurensius mengajarkan bahwa kaum papa adalah tubuh mistik Kristus yang menjadi perbendaharaan sejati Gereja.');
addQ(5, 'sulit', 'Penerapan Moto AMDG Bagi Prestasi Pelajar', 'Bagaimana seorang siswa kelas 5 katolik menghayati moto "Ad Maiorem Dei Gloriam" (AMDG) saat mempersiapkan diri menghadapi kompetisi cerdas cermat sains?', ['Belajar siang malam hanya agar fotonya dipajang di spanduk sekolah dan dipuji teman', 'Mengerjakan seluruh ikhtiar kecerdasan belajar secara jujur dan mempersembahkan hasil prestasi tersebut semata-mata untuk memuliakan Tuhan dan berguna bagi sesama, bukan untuk kesombongan ego', 'Menyontek rumus agar pasti menang', 'Menghalalkan segala cara mengalahkan lawan'], 1, 'AMDG menguduskan seluruh motivasi belajar: bukan mengejar kesombongan diri melainkan mempersembahkan yang terbaik demi kemuliaan Allah.');
addQ(5, 'sulit', 'Carlo Acutis dan Kesucian Zaman Digital', 'Beato Carlo Acutis berkata: "Semua orang dilahirkan sebagai karya asli (orisinil), tetapi banyak orang mati sebagai fotokopian (tiruan)". Makna peringatan rohani ini bagi remaja pengguna internet adalah ...', ['Jangan memfotokopi buku pelajaran di perpustakaan', 'Jangan membiarkan diri diperbudak oleh tren fana media sosial yang seragam dan merusak moral, melainkan kembangkanlah rencana unik kekudusan yang dirancang Allah bagi dirimu', 'Setiap anak harus membeli kamera canggih untuk membuat konten', 'Menolak berteman di media sosial'], 1, 'Carlo Acutis mengingatkan kita untuk setia pada jati diri unik sebagai ciptaan Allah dan tidak larut menjadi tiruan dangkal tren dosa duniawi.');
addQ(5, 'sulit', 'Roh Kudus dan Keberanian Kesaksian Publik', 'Sakramen Penguatan memberikan meterai Roh Kudus yang memampukan penerimanya menjadi saksi Kristus (martys) di tengah ruang publik. Penerapannya bagi siswa katolik di sekolah umum adalah ...', ['Memaksa teman sekelas menghafal doa Salam Maria', 'Berani berdiri teguh pada nilai-nilai keadilan, tidak malu berdoa sebelum makan, menolak ajakan berbuat curang, dan menebarkan kasih persaudaraan tanpa rasa takut diintimidasi', 'Menyembunyikan identitas agamanya rapat-rapat', 'Memusuhi guru yang berbeda agama'], 1, 'Sakramen Krisma memberikan keberanian moral (fortitudo) untuk bersaksi bagi kebenaran dan kasih Kristus di tengah masyarakat majemuk.');
addQ(5, 'sulit', 'Kritik Yesus Terhadap Kaum Farisi dan Saduki', 'Yesus memperingatkan murid-murid-Nya: "Waspadalah terhadap ragi orang Farisi dan Saduki". Apakah "ragi" berbahaya yang dimaksud oleh Yesus?', ['Ragi pembuat kue yang sudah kedaluwarsa', 'Kemunafikan kesalehan lahiriah orang Farisi yang suka pamer dan rasionalisme skeptis orang Saduki yang menolak kebangkitan orang mati serta campur tangan Allah', 'Tepung terigu murah dari pasar gandum', 'Tradisi makan bersama para imam bait suci'], 1, 'Ragi Farisi dan Saduki adalah racun kemunafikan pencitraan moral dan ketidakpercayaan pada kuasa kebangkitan Ilahi.');
addQ(5, 'sulit', 'Analisis Teologis Sakramen Pengurapan: Kapan Diterimakan?', 'Gereja Katolik mengajarkan bahwa Sakramen Pengurapan Orang Sakit bukanlah "sakramen kematian" (bukan hanya untuk orang yang sedang sekarat detik-detik terakhir), melainkan dapat diterimakan kepada ...', ['Siapa saja yang merasa sedikit pusing kepala', 'Orang beriman yang mulai berada dalam bahaya maut karena sakit berat, usia lanjut yang semakin lemah, atau menjelang operasi bedah besar', 'Hanya para imam dan biarawan di rumah sakit', 'Anak-anak yang sedang malas bersekolah'], 1, 'Sakramen Pengurapan mendampingi orang beriman yang menghadapi kerapuhan sakit berat dengan rahmat penguatan dan penghiburan Kristus.');
addQ(5, 'sulit', 'Tantangan Menolak Budaya Konsumerisme Buang-Pakai', 'Paus Fransiskus mengkritik keras "budaya buang-pakai" (throwaway culture) yang tidak hanya memperlakukan barang sebagai sampah tetapi juga memperlakukan manusia lemah sebagai beban. Tanggung jawab etis kita adalah ...', ['Membeli barang elektronik baru setiap bulan', 'Menghargai martabat setiap insan manusia yang rapuh (kaum lansia, difabel, kaum miskin) dan merawat barang ciptaan dengan hemat serta bijak', 'Membuang sisa makanan yang masih layak makan', 'Mengucilkan kakek dan nenek yang sudah pikun'], 1, 'Menentang budaya buang-pakai menuntut penghargaan terhadap martabat luhur manusia yang rapuh serta penatalayanan ekologis yang bijaksana.');
addQ(5, 'sulit', 'Makna "In Persona Christi Capitis" Sakramen Imamat', 'Dalam liturgi Ekaristi, imam bertindak "in persona Christi Capitis", yang memiliki makna teologis bahwa ...', ['Imam adalah manusia paling suci tanpa dosa di bumi', 'Imam ditahbiskan untuk bertindak dalam pribadi Kristus Sang Kepala Gereja, menghadirkan kembali kurban salib Kristus secara sakramental bagi umat-Nya', 'Imam berhak memerintah seluruh harta umat paroki', 'Imam boleh mengubah isi Alkitab sesuai keinginannya'], 1, 'In persona Christi menegaskan bahwa imam adalah bejana pelayan; Kristus sendirilah yang bertindak sebagai Imam Agung dalam sakramen.');
addQ(5, 'sulit', 'Perlawanan Terhadap Sikap Korupsi Sejak Dini', 'Bagaimana seorang siswa kelas 5 katolik mempraktikkan perlawanan terhadap budaya korupsi dalam kepengurusan kas kelas?', ['Menggunakan sedikit uang kas untuk membeli jajan pribadi asal tidak ketahuan', 'Mencatat setiap pemasukan dan pengeluaran kas kelas secara jujur, transparan, dan tidak mengambil satu rupiah pun hak milik bersama', 'Menghilangkan buku laporan kas saat ditanya guru', 'Memberikan laporan palsu demi menyenangkan teman dekat'], 1, 'Integritas finansial dan transparansi dalam mengelola uang bersama adalah fondasi moral pencegahan korupsi sejak usia dini.');
addQ(5, 'sulit', 'Kearifan Kisah Pertobatan Santa Maria Magdalena', 'Santa Maria Magdalena yang dibebaskan Yesus dari tujuh roh jahat menjadi orang pertama yang menyaksikan kebangkitan Kristus dan diutus memberitakannya kepada para rasul. Gelar terhormat yang diberikan Gereja kepadanya adalah ...', ['Ratu Para Malaikat', 'Apostola Apostolorum (Rasul Para Rasul)', 'Doktor Gereja Roma', 'Penguasa kota Yerusalem'], 1, 'Santa Maria Magdalena diberi gelar kehormatan "Rasul Para Rasul" atas kesetiaannya menjadi pewarta pertama kabar kebangkitan Kristus.');
addQ(5, 'sulit', 'Analisis Keteladanan Santo Thomas More', 'Santo Thomas More, perdana menteri Inggris, rela dihukum pancung lehernya oleh Raja Henry VIII daripada menandatangani persetujuan perceraian raja yang melanggar hukum Gereja. Sebelum wafat ia berkata: "Aku adalah hamba setia raja, tetapi ..."', ['"Aku lebih mencintai emas kerajaan"', '"Allah adalah yang pertama"', '"Aku takut pada hukuman penjara"', '"Biarkan aku melarikan diri ke Spanyol"'], 1, 'Santo Thomas More adalah martir suara hati nurani: ketaatan pada hukum Allah berdiri di atas segala tekanan kekuasaan penguasa fana.');
addQ(5, 'sulit', 'Makna "Gereja yang Senantiasa Bertobat" (Semper Reformanda)', 'Gereja Katolik mengakui ungkapan "Ecclesia semper reformanda est", yang bermakna bahwa Gereja peziarah di bumi ...', ['Harus mengganti Sepuluh Perintah Allah setiap abad', 'Perlu senantiasa memperbarui diri, memurnikan diri dari kelemahan dosa anggotanya, dan kembali setia pada kemurnian Injil Kristus', 'Boleh membubarkan diri jika ada masalah perpecahan', 'Harus mengikuti seluruh arus tren sekular modern'], 1, 'Semper reformanda adalah panggilan pembaruan spiritual terus-menerus agar Gereja semakin menyerupai kekudusan Mempelainya, Kristus.');
addQ(5, 'sulit', 'Pemberian Terbesar Pengorbanan Santo Maksimilianus Kolbe', 'Di kamp konsentrasi Auschwitz zaman Nazi, Pastor Maksimilianus Kolbe secara sukarela menawarkan dirinya dihukum mati kelaparan di bunker maut untuk menggantikan seorang ayah keluarga bernama Franciszek Gajowniczek. Teladan pengorbanan Kolbe menggenapi sabda Yesus: ...', ['"Mata ganti mata, gigi ganti gigi"', '"Tidak ada kasih yang lebih besar dari pada kasih seorang yang memberikan nyawanya untuk sahabat-sahabatnya" (Yohanes 15:13)', '"Janganlah kamu membawa uang di ikat pinggangmu"', '"Kumpulkanlah harta di dalam lumbung"'], 1, 'Santo Maksimilianus Kolbe meneladankan puncak kasih pengorbanan Kristiani: rela mati menggantikan nyawa sesama.');
addQ(5, 'sulit', 'Tantangan Menjaga Doa Batin di Tengah Kesibukan', 'Metode Doa Hening Meditasi Kristiani (Lectio Divina) mengajak orang beriman membaca Kitab Suci dengan empat tahapan teratur yaitu: Lectio (membaca), Meditatio (merenungkan), Oratio (berdoa), dan ...', ['Disputatio (berdebat)', 'Contemplatio (berkontemplasi dalam keheningan hadirat Allah)', 'Memorizatio (menghafal kata per kata)', 'Dormitio (tidur nyenyak)'], 1, 'Lectio Divina menuntun jiwa: membaca sabda, merenungkan maknanya, menaikkan doa batin, dan beristirahat dalam kontemplasi hadirat Allah.');
addQ(5, 'sulit', 'Menilai Integritas Mengakui Bakat Teman', 'Bila teman sebangku kita memiliki bakat bernyanyi atau berpidato yang jauh lebih unggul dari kita, respons batin yang sehat menurut ajaran Santo Paulus (Roma 12:10) adalah ...', ['Merasa iri hati dan menyebarkan rumor buruk tentangnya', 'Bersukacita atas karunia yang diterimanya, saling mengasihi sebagai saudara, dan saling mendahului dalam memberi hormat', 'Menolak berbicara dengannya di kelas', 'Berusaha menyabotase penampilannya'], 1, 'Kasih persaudaraan kristiani menuntut kita bersukacita atas keberhasilan sesama dan mengikis penyakit iri dengki.');

addQ(5, 'sulit', 'Pertobatan Santo Agustinus Tolle Lege', 'Ketika Santo Agustinus bergulat melawan hawa nafsu keduniawian di sebuah taman di Milan, ia mendengar suara misterius bersenandung "Tolle, lege" (Ambillah dan bacalah!). Ayat Alkitab Roma 13 yang dibukanya langsung menyadarkannya untuk ...', ['Membeli rumah baru di Afrika', 'Meninggalkan perbuatan kegelapan pesta pora dan mengenakan perlengkapan senjata terang Yesus Kristus', 'Menjadi jenderal tentara Romawi', 'Menolak belajar filsafat'], 1, 'Kisah pertobatan Agustinus membuktikan kuasa firman Allah yang sanggup melahirkan manusia baru dari lumpur dosa.');
addQ(5, 'sulit', 'Maria Tabut Perjanjian Baru', 'Gereja Katolik menyapa Bunda Maria sebagai "Tabut Perjanjian Baru" (Arca Foederis). Landasan teologis gelar ini adalah karena Maria mengandung di dalam rahimnya ...', ['Dua loh batu Dasa Firman Musa', 'Yesus Kristus Sang Roti Hidup, Imam Agung, dan Firman Allah yang hidup berinkarnasi', 'Kitab Taurat emas dari Yerusalem', 'Manna gurun pasir yang diawetkan'], 1, 'Jika tabut Perjanjian Lama memuat loh batu hukum, Maria memuat Kristus Sang Penggenap hukum dan Sumber Hidup sejati.');
addQ(5, 'sulit', 'Kedewasaan Iman Sakramen Krisma', 'Mengapa Sakramen Krisma sering disebut sebagai sakramen kedewasaan rohani (sakramen pendewasaan iman)?', ['Karena penerimanya langsung diberi pekerjaan di paroki', 'Karena penerimanya secara sadar memperbarui janji baptis atas kemauan sendiri dan menerima kekuatan Roh Kudus untuk membela iman di tengah masyarakat', 'Karena setelah krisma tidak perlu lagi mengikuti pelajaran agama', 'Hanya tradisi perayaan ulang tahun ke-17'], 1, 'Krisma menandai kedewasaan iman: beralih dari iman warisan anak-anak menuju komitmen iman pribadi yang berani bertanggung jawab.');
addQ(5, 'sulit', 'Humanae Vitae Transmisi Kehidupan', 'Ensiklik Paus Paulus VI "Humanae Vitae" (1968) menegaskan bahwa transmisi kehidupan dalam perkawinan memiliki dua makna hakiki yang tak terpisahkan yaitu ...', ['Kekayaan materi dan status sosial', 'Makna persatuan cinta kasih suami-istri (unitif) dan makna keterbukaan pada penerusan keturunan kehidupan manusia (prokreatif)', 'Kekuasaan politik dan hak waris', 'Pesta pernikahan dan liburan keluarga'], 1, 'Gereja mengajarkan perkawinan memadukan kasih persatuan suami-istri dan keterbukaan menyambut anugerah kehidupan anak.');
addQ(5, 'sulit', 'Panggilan Selibat Demi Kerajaan Allah', 'Para imam diosesan dan religius katolik mengikrarkan hidup selibat (tidak menikah). Nilai spiritual terdalam dari hidup selibat ini adalah ...', ['Karena membenci lawan jenis', 'Penyerahan hati secara utuh dan tak terbagi untuk mengasihi Kristus dan melayani seluruh umat Allah tanpa ikatan keluarga pribadi', 'Karena menghemat biaya pesta pernikahan', 'Hanya peraturan tata tertib biara kuno'], 1, 'Selibat adalah karunia profetis: penyerahan cinta total demi melayani segenap jemaat sebagai keluarga rohani Allah.');
addQ(5, 'sulit', 'Perumpamaan Lalang di Antara Gandum', 'Dalam perumpamaan lalang di antara gandum (Matius 13), tuan ladang melarang pelayan mencabuti lalang sebelum waktu panen tiba. Kebijaksanaan Allah di balik perumpamaan ini adalah ...', ['Tuan ladang menyukai tanaman lalang liar', 'Kesabaran Allah memberi waktu bagi orang berdosa untuk bertobat dan menghindari tercabutnya orang benar secara keliru sebelum penghakiman akhir', 'Lalang rasanya manis seperti gandum', 'Supaya ladang terlihat rimbun hijau'], 1, 'Matius 13:29: Allah sabar menanti pertobatan manusia dan tidak tergesa-gesa membinasakan orang bersalah sebelum hari penghakiman.');
addQ(5, 'sulit', 'Jalan Kecil Santa Theresia Lisieux', 'Santa Theresia dari Kanak-kanak Yesus mengajarkan spiritualitas "Jalan Kecil" (Petite Voie) menuju surga. Inti dari Jalan Kecil ini adalah ...', ['Melakukan perjalanan ziarah melintasi jalan setapak di desa', 'Melakukan hal-hal kecil dan sederhana sehari-hari dengan cinta kasih yang luar biasa besar demi menyenangkan hati Tuhan', 'Menolak memegang tanggung jawab besar di sekolah', 'Berbicara dengan suara kecil berbisik'], 1, 'Jalan Kecil mengajarkan bahwa kekudusan dapat dicapai oleh siapa saja melalui kesetiaan pada tugas kecil yang dijiwai kasih murni.');
addQ(5, 'sulit', 'Pesan Penampakan Bunda Maria di Fatima', 'Pada tahun 1917 Bunda Maria menampakkan diri kepada tiga anak gembala (Lusia, Fransiskus, Yasinta) di Fatima Portugal. Inti pesan Maria yang relevan bagi perdamaian dunia adalah ...', ['Membangun benteng persenjataan militer', 'Panggilan pertobatan hidup, doa Rosario setiap hari, dan silih mati raga demi perdamaian dunia dan pertobatan orang berdosa', 'Membeli perhiasan emas untuk gereja', 'Meninggalkan pekerjaan bertani domba'], 1, 'Pesan Fatima menekankan pertobatan, doa Rosario harian, dan solidaritas doa demi meredakan perang dan mendatangkan damai.');
addQ(5, 'sulit', 'Doa Santo Fransiskus Pembawa Damai', 'Doa termasyhur Santo Fransiskus Asisi berbunyi: "Tuhan, jadikanlah aku pembawa damai-Mu... di mana ada kebencian, jadikanlah aku pembawa ..."', ['Dendam yang membara', 'Cinta kasih; di mana ada penghinaan, jadikanlah aku pembawa pengampunan', 'Batu pemukul lawan', 'Gosip yang menyebar luas'], 1, 'Doa Fransiskus merangkum etika damai kristiani: mengatasi kebencian dengan cinta dan penghinaan dengan pengampunan.');
addQ(5, 'sulit', 'Darah Para Martir Benih Gereja', 'Pujangga Gereja perdana Tertulianus menuliskan ungkapan agung: "Semen est sanguis christianorum" (Darah orang kristiani adalah benih Gereja). Makna sejarah dari pernyataan ini adalah ...', ['Orang kristiani menyukai pertumpahan darah', 'Setiap kali orang beriman dianiaya dan mati sebagai martir karena setia pada Kristus, iman jemaat justru semakin bertumbuh subur dan menghasilkan ribuan orang bertobat', 'Gereja punah setelah kaisar membunuh para martir', 'Orang beriman harus melarikan diri ke hutan'], 1, 'Keteguhan iman para martir menghadapi maut menjadi kesaksian tak terbantahkan yang melahirkan gelombang kebangkitan iman jemaat.');

addQ(6, 'mudah', 'Empat Sifat Gereja', 'Empat sifat hakiki Gereja Katolik sebagaimana diikrarkan dalam Syahadat iman adalah Gereja yang Satu, Kudus, Katolik, dan ...', ['Apostolik', 'Kharismatik', 'Tradisional', 'Monarki'], 0, 'Empat sifat Gereja Katolik: Satu (Una), Kudus (Sancta), Katolik (Catholica), dan Apostolik (Apostolica).');
addQ(6, 'mudah', 'Pemimpin Tertinggi Gereja', 'Pemimpin tertinggi Gereja Katolik sedunia sekaligus Uskup Roma dan penerus takhta Santo Petrus adalah ...', ['Kardinal', 'Paus (Bapa Suci)', 'Uskup Agung', 'Pastor Paroki'], 1, 'Paus adalah gembala tertinggi Gereja Katolik semesta berkedudukan di Tahta Suci Vatikan.');
addQ(6, 'mudah', 'Paus Pertama', 'Rasul yang ditetapkan langsung oleh Tuhan Yesus menjadi pemimpin para rasul dan paus pertama dalam sejarah Gereja adalah Santo ...', ['Petrus', 'Paulus', 'Andreas', 'Yohanes'], 0, 'Yesus bersabda kepada Simon Petrus: "Gembalakanlah domba-domba-Ku" dan menyerahkan kunci Kerajaan Surga.');
addQ(6, 'mudah', 'Pemimpin Keuskupan', 'Pemimpin tertinggi gereja lokal di suatu wilayah Keuskupan adalah seorang ...', ['Bapak Uskup', 'Frater Kepala', 'Biarawati', 'Kepala Sekolah'], 0, 'Uskup adalah gembala utama keuskupan lokal penerus para rasul.');
addQ(6, 'mudah', 'Arti Sifat Apostolik', 'Sifat Gereja "Apostolik" memiliki arti bahwa Gereja Katolik didirikan di atas dasar ajaran dan perutusan dari ...', ['Para kaisar Romawi kuno', 'Para rasul Yesus Kristus', 'Para filsuf Yunani', 'Para raja Eropa'], 1, 'Apostolik berarti setia berakar pada tradisi, ajaran, dan suksesi kepemimpinan para rasul.');
addQ(6, 'mudah', 'Ensiklik Fratelli Tutti', 'Ensiklik Paus Fransiskus yang bertemakan tentang persaudaraan insani universal dan persahabatan sosial berjudul ...', ['Laudato Si\'', 'Fratelli Tutti', 'Lumen Gentium', 'Evangelii Gaudium'], 1, 'Fratelli Tutti ("Semua Bersaudara") menyerukan persaudaraan universal melampaui batas geografis dan agama.');
addQ(6, 'mudah', 'Api Penyucian Purgatorium', 'Keadaan pemurnian jiwa bagi orang-orang beriman yang meninggal dalam kasih karunia Allah sebelum masuk ke dalam kemuliaan surga dinamakan ...', ['Limbo', 'Api Penyucian (Purgatorium)', 'Lembah Hinnom', 'Gua pertapaan'], 1, 'Api Penyucian adalah proses pembersihan kerahiman ilahi bagi jiwa agar mencapai kesucian mutlak memandang Allah.');
addQ(6, 'mudah', 'Kebahagiaan Surga', 'Surga dalam ajaran iman Katolik adalah kebahagiaan abadi bersatu muka dengan muka memandang kemuliaan Allah Tritunggal yang disebut ...', ['Nirwana fana', 'Visio Beatifica (Pandangan yang Membahagiakan)', 'Reinkarnasi bumi', 'Tidur panjang abadi'], 1, 'Visio Beatifica adalah perjumpaan penuh sukacita memandang Allah dalam keabadian surga.');
addQ(6, 'mudah', 'Pelindung Pendidik', 'Santo pelindung para guru dan pendidik katolik yang mendirikan kongregasi Bruder De La Salle adalah Santo ...', ['Yohanes Pembaptis de La Salle', 'Ignatius Loyola', 'Aloysius Gonzaga', 'Klemens Hofbauer'], 0, 'Santo Yohanes Pembaptis de La Salle adalah pelindung surgawi kaum guru dan pendidik.');
addQ(6, 'mudah', 'Kaum Awam', 'Seluruh umat beriman katolik yang bukan merupakan klerus (tertahbis) maupun biarawan/biarawati yang berkaul dinamakan kaum ...', ['Misdinar', 'Awam (Laici)', 'Kolektan', 'Koor'], 1, 'Kaum Awam dipanggil menguduskan tata dunia fana (keluarga, profesi kerja, masyarakat) dari dalam.');

addQ(6, 'sedang', 'Sifat Gereja Satu', 'Gereja Katolik bersifat "Satu" karena disatukan oleh satu sumber Tritunggal, satu pengakuan iman yang sama, satu perayaan sakramen, dan satu kepemimpinan penerus ...', ['Kaisar Konstantin', 'Santo Petrus (Paus)', 'Raja Salomo', 'Nabi Musa'], 1, 'Kesatuan Gereja bersumber dari kesatuan Allah Tritunggal dan terpelihara di bawah kepemimpinan penerus Petrus.');
addQ(6, 'sedang', 'Sifat Gereja Kudus', 'Gereja Katolik bersifat "Kudus" bukan karena semua anggotanya bebas dari dosa, melainkan karena ...', ['Seluruh anggotanya mengenakan jubah putih', 'Kristus adalah Pendiri dan Kepalanya yang menguduskan Gereja melalui pengorbanan salib dan Roh Kudus', 'Gedung gereja terbuat dari batu marmer mahal', 'Gereja tidak memiliki kelemahan manusiawi'], 1, 'Kekudusan Gereja berasal dari kekudusan Kristus yang menyucikan Mempelai-Nya melalui sakramen.');
addQ(6, 'sedang', 'Sifat Gereja Katolik', 'Sifat Gereja "Katolik" (Universal) menegaskan bahwa Gereja diutus Kristus untuk mewartakan keselamatan kepada ...', ['Hanya orang-orang kaya di kota besar', 'Seluruh umat manusia dari segala bangsa, ras, suku, dan budaya di muka bumi', 'Bangsa Eropa semata', 'Orang yang fasih berbahasa Latin saja'], 1, 'Katolik berarti universal: merangkul seluruh bangsa dan kebudayaan ke dalam satu persekutuan iman.');
addQ(6, 'sedang', 'Suksesi Apostolik', 'Penerusan kuasa jabatan penggembalaan dari para rasul kepada para uskup melalui penumpangan tangan sakramen imamat tanpa putus dinamakan ...', ['Suksesi Apostolik', 'Demokrasi gereja', 'Pemilihan umum paroki', 'Pemberian gelar bangsawan'], 0, 'Suksesi apostolik menjamin kesinambungan ajaran, wewenang penggembalaan, dan keabsahan sakramen sejak zaman rasul.');
addQ(6, 'sedang', 'Peran Kerasulan Awam', 'Berdasarkan dokumen Konsili Vatikan II Apostolicam Actuositatem, tugas kerasulan kaum awam di tengah dunia adalah menjadi ...', ['Penonton pasif di gereja', 'Garam dan terang di bidang politik, ekonomi, sains, kebudayaan, dan profesi kerja', 'Pengganti tugas pastor memimpin misa', 'Petugas pemungut pajak negara'], 1, 'Kaum awam menguduskan dunia fana dari dalam dengan menghadirkan nilai Injil dalam profesi kerja harian.');
addQ(6, 'sedang', 'Budaya Perjumpaan Fratelli', 'Dalam ensiklik Fratelli Tutti, Paus Fransiskus mengajak umat dunia mengembangkan "budaya perjumpaan" (culture of encounter) yang bertujuan untuk ...', ['Membuat pesta kembang api bersama', 'Mengatasi sikap acuh tak acuh, meruntuhkan tembok prasangka, dan membangun dialog persaudaraan yang tulus', 'Menutup perbatasan antar negara', 'Mewajibkan semua orang memakai bahasa yang sama'], 1, 'Budaya perjumpaan merangkul sesama melampaui sekat kecurigaan menuju persaudaraan sejati.');
addQ(6, 'sedang', 'Doa Arwah Bulan November', 'Gereja Katolik mendedikasikan bulan November secara khusus untuk mendoakan arwah orang-orang beriman di api penyucian sebagai wujud ...', ['Ketakutan pada hantu di kuburan', 'Solidaritas cinta kasih dan doa syafaat dalam Persekutuan Para Kudus', 'Tradisi menghias batu nisan semata', 'Hanya kewajiban pengurus makam paroki'], 1, 'Mendoakan jiwa-jiwa di api penyucian adalah karya belas kasih rohani dalam kesatuan Persekutuan Para Kudus.');
addQ(6, 'sedang', 'Tiga Kaul Hidup Bakti', 'Tiga kaul suci (nasihat injili) yang diikrarkan oleh para biarawan dan biarawati Katolik adalah kaul kemiskinan, kaul ketaatan, dan kaul ...', ['Kekayaan', 'Kemurnian (Keperawanan/Selibat)', 'Kekuatan fisik', 'Kebebasan mutlak'], 1, 'Tiga nasihat Injil: kemiskinan sukarela, kemurnian/selibat demi Kerajaan Surga, dan ketaatan kepada pimpinan rohani.');
addQ(6, 'sedang', 'Menolak Ujaran Kebencian Digital', 'Sikap seorang murid katolik kelas 6 dalam menghadapi maraknya hoaks dan ujaran kebencian di media sosial adalah ...', ['Ikut menyebarkannya agar viral di grup sekolah', 'Menyaring kebenaran informasi secara kritis, menolak membagikan kabar dusta, dan menyebarkan pesan perdamaian', 'Membuat akun palsu untuk menyerang lawan', 'Menghasut teman agar memusuhi kelompok lain'], 1, 'Kecerdasan bermedia sosial menuntut integritas kebenaran, kesantunan bertutur kata, dan cinta damai.');
addQ(6, 'sedang', 'Ajaran Sosial Gereja dan HAM', 'Ajaran Sosial Gereja (ASG) menegaskan bahwa Hak Asasi Manusia (HAM) harus dihormati dan dilindungi karena bersumber langsung dari ...', ['Pemberian cuma-cuma undang-undang pemerintah', 'Martabat luhur manusia sebagai ciptaan seturut Citra Allah yang berdaulat', 'Kemenangan perang suatu negara', 'Besarnya pajak yang dibayar warga'], 1, 'HAM berakar pada martabat manusia ciptaan Allah yang kudus dan tidak boleh dirampas oleh kekuasaan apa pun.');
addQ(6, 'sedang', 'Kematian Pintu Gerbang Kehidupan Kekal', 'Prefasi Misa Arwah menegaskan: "Bagi orang beriman, hidup hanyalah diubah, bukan dilenyapkan". Makna iman kristiani tentang kematian adalah ...', ['Kematian adalah kepunahan manusia seutuhnya menjadi tanah', 'Kematian adalah pintu gerbang peralihan dari kemah fana duniawi menuju kediaman abadi di surga bersama Kristus', 'Kematian adalah kutukan dendam Allah', 'Jiwa manusia akan berpindah ke tubuh hewan baru'], 1, 'Kematian jasmani adalah transisi mistik menuju perjumpaan abadi dengan Allah bagi jiwa yang setia.');
addQ(6, 'sedang', 'Batu Karang Santo Petrus', 'Yesus bersabda kepada Simon dalam Matius 16:18: "Engkau adalah Petrus dan di atas batu karang ini Aku akan mendirikan ..."', ['Istana megah di Roma', 'Jemaat-Ku (Gereja-Ku) dan alam maut tidak akan menguasainya', 'Benteng perunggu kaisar', 'Bait suci baru berlantai emas'], 1, 'Petrus (Kephas) ditetapkan Kristus sebagai batu karang fondasi kepemimpinan dan kesatuan Gereja.');
addQ(6, 'sedang', 'Integritas Melawan Korupsi Sekolah', 'Ketika terpilih menjadi bendahara panitia perpisahan kelas 6, wujud integritas moral kristiani adalah ...', ['Memakai sisa uang kas untuk mentraktir sahabat dekat', 'Mengelola dan mempertanggungjawabkan setiap rupiah dana perpisahan secara terbuka, rapi, jujur, dan tidak menyelewengkan uang kas', 'Memanipulasi nota kuitansi belanja', 'Menolak memperlihatkan buku kas kepada wali kelas'], 1, 'Integritas bendahara membuktikan ketulusan moral dan tanggung jawab keadilan di hadapan Allah dan sesama.');
addQ(6, 'sedang', 'Dialog Kemanusiaan Lintas Agama', 'Bentuk kerja sama dialog karya antarumat beragama yang paling nyata di Indonesia dicontohkan dengan ...', ['Memperdebatkan tata cara doa di media sosial', 'Bersama-sama mendirikan posko dapur umum menolong korban banjir bandang tanpa memandang perbedaan agama', 'Mengasingkan diri dari pergaulan warga RT', 'Membuat pagar pemisah antar perkampungan'], 1, 'Dialog karya kemanusiaan merajut persaudaraan sejati melalui aksi nyata menolong sesama yang menderita.');
addQ(6, 'sedang', 'Hierarki Pelayanan Gereja', 'Struktur hierarki pelayanan dalam Gereja Katolik secara berjenjang dari gembala tertinggi hingga pembantu imam adalah ...', ['Paus, Uskup, Imam, dan Diakon', 'Kaisar, Raja, Pangeran, dan Prajurit', 'Kepala Sekolah, Guru, Murid, dan Satpam', 'Presiden, Menteri, Gubernur, dan Camat'], 0, 'Hierarki suci tertahbis terdiri dari Uskup Roma (Paus), para Uskup, para Imam (presbiter), dan para Diakon.');
addQ(6, 'sedang', 'Konsili Pembaharuan Vatikan II', 'Konsili ekumenis ke-21 yang diadakan di Basilika Santo Petrus Vatikan pada tahun 1962-1965 untuk memperbarui hidup Gereja di era modern adalah Konsili ...', ['Trente', 'Vatikan II', 'Nicea', 'Konstantinopel'], 1, 'Konsili Vatikan II adalah peristiwa rahmat agung yang membuka jendela pembaruan pastoral Gereja di era modern.');
addQ(6, 'sedang', 'Semangat Aggiornamento Paus Yohanes XXIII', 'Paus Santo Yohanes XXIII memprakarsai Konsili Vatikan II dengan seruan "Aggiornamento", yang memiliki arti ...', ['Membakar buku-buku perpustakaan lama', 'Pembaruan dan penyesuaian pastoral Gereja dengan zaman modern tanpa mengubah pokok kebenaran iman', 'Menghapuskan bahasa Latin selamanya', 'Mengubah Sepuluh Perintah Allah'], 1, 'Aggiornamento berarti membawa Gereja mutakhir menyapa dunia modern dengan bahasa kasih yang relevan.');
addQ(6, 'sedang', 'Ekologi Integral Rumah Bersama', 'Paus Fransiskus mengajarkan "Ekologi Integral", yaitu pemahaman bahwa krisis lingkungan hidup tidak dapat dipisahkan dari masalah ...', ['Harga tiket penerbangan luar angkasa', 'Keadilan sosial dan pembelaan hak-hak kaum miskin yang paling terdampak oleh kerusakan alam', 'Pembangunan gedung pencakar langit', 'Kekurangan kuota internet'], 1, 'Ekologi integral memadukan jeritan bumi dan jeritan kaum miskin sebagai satu krisis kemanusiaan utuh.');
addQ(6, 'sedang', 'Doa Perutusan Kelulusan SD', 'Menjelang menamatkan pendidikan SD dan melangkah ke bangku SMP, sikap iman seorang murid katolik adalah ...', ['Merasa sombong karena sudah menjadi anak besar', 'Bersyukur atas didikan guru, memohon pimpinan Roh Kudus agar terus bertumbuh dalam iman, ilmu, dan karakter mulia sebagai duta Kristus', 'Berhenti belajar dan bermain game seharian', 'Melupakan semua teman dan guru lama'], 1, 'Kelulusan adalah batu loncatan perutusan hidup baru untuk terus memancarkan terang Kristus di jenjang SMP.');
addQ(6, 'sedang', 'Toleransi Rukun Warga NKRI', 'Di Indonesia yang berdasarkan Pancasila, murid katolik mengamalkan nilai Sila ke-1 "Ketuhanan Yang Maha Esa" dan Sila ke-3 "Persatuan Indonesia" dengan cara ...', ['Hanya mau berteman dengan anak yang satu gereja', 'Menghormati hak ibadah pemeluk agama lain, menjalin silaturahmi damai, dan mengutamakan persatuan bangsa di atas kepentingan golongan', 'Membuat keributan saat perayaan hari besar agama tetangga', 'Memaksa kawan lain mengikuti keyakinan kita'], 1, 'Kerukunan antarumat beragama memperkokoh keutuhan bangsa Indonesia yang bersemboyan Bhinneka Tunggal Ika.');

addQ(6, 'sulit', 'Teologi Kekudusan Gereja Semper Reformanda', 'Mengapa Gereja Katolik disebut "Kudus" dalam Syahadat iman, padahal dalam sejarahnya banyak anggotanya (bahkan pejabat tertahbis) yang jatuh ke dalam dosa kelemahan manusiawi?', ['Karena Gereja menyembunyikan kesalahan masa lalunya', 'Kekudusan Gereja bersumber mutlak dari Kristus Sang Kepala yang menguduskannya dan Roh Kudus yang memimpinnya; Gereja adalah persekutuan orang berdosa yang senantiasa dipanggil bertobat dan memurnikan diri (Ecclesia semper reformanda)', 'Karena orang berdosa langsung dikeluarkan dari gereja', 'Hanya gelar seremonial diplomatik di PBB'], 1, 'Kekudusan Gereja bukan prestasi moral manusiawi, melainkan anugerah rahmat Kristus yang tak pernah meninggalkan Mempelai-Nya.');
addQ(6, 'sulit', 'Makna Suksesi Apostolik Menjamin Doktrin', 'Mengapa suksesi apostolik (pergantian para uskup dari para rasul tanpa putus) sangat krusial bagi keutuhan iman Gereja Katolik?', ['Supaya gereja memiliki arsip sejarah silsilah keluarga tertua di Eropa', 'Menjamin bahwa ajaran iman, wewenang penggembalaan, dan rahmat sakramen yang kita rayakan hari ini bersambung asli dan murni dari Kristus dan para rasul tanpa distorsi atau rekayasa sesat', 'Agar uskup selalu dipilih dari garis keturunan para rasul', 'Hanya peraturan administratif hukum kanonik gereja'], 1, 'Suksesi apostolik adalah mata rantai penjamin keaslian transmisi wahyu Ilahi dan keabsahan sakramen sepanjang zaman.');
addQ(6, 'sulit', 'Model Samaria Murah Hati dalam Fratelli Tutti', 'Dalam ensiklik Fratelli Tutti bab 2, Paus Fransiskus menggunakan perumpamaan Orang Samaria yang Murah Hati sebagai cermin bagi dunia modern. Kritik Paus terhadap masyarakat modern saat ini adalah ...', ['Masyarakat modern kurang mahir menunggang keledai', 'Banyak orang bersikap acuh tak acuh seperti imam dan orang Lewi, sibuk dengan kepentingannya sendiri dan melangkah pergi membiarkan sesama yang terluka tergeletak di pinggir jalan', 'Jalan antara Yerusalem dan Yerikho sekarang terlalu ramai', 'Orang Samaria tidak memakai masker kesehatan'], 1, 'Fratelli Tutti mengecam globalisasi ketidakpedulian (globalization of indifference) dan memanggil kita menjadi sesama yang merawat luka dunia.');
addQ(6, 'sulit', 'Konsep Purgatorium Kerahiman Allah', 'Bagaimana teologi katolik memandang api penyucian (Purgatorium) sebagai wujud kerahiman cinta Allah dan bukan tempat pembalasan dendam?', ['Purgatorium adalah tempat pembakaran sampah dosa akhirat', 'Api penyucian adalah proses pembersihan cinta ilahi yang menyucikan sisa-sisa keterikatan dosa manusia agar jiwa bersih murni seutuhnya sebelum memandang keagungan Allah yang Mahasuci', 'Purgatorium diciptakan agar manusia membayar uang doa arwah', 'Jiwa di api penyucian tidak memiliki harapan masuk surga'], 1, 'Purgatorium adalah anugerah pemurnian kerahiman: api cinta ilahi yang membakar noda dosa agar jiwa layak masuk ke dalam kebahagiaan surgawi.');
addQ(6, 'sulit', 'Peran Kaum Awam Menguduskan Dunia Temporal', 'Dokumen Lumen Gentium artikel 31 menegaskan ciri khas panggilan kaum awam adalah hidup di tengah dunia temporal. Peran kerasulan kaum awam katolik di tengah masyarakat adalah ...', ['Mengambil alih tugas imam membagikan komuni di altar', 'Menguduskan dunia dari dalam laksana ragi: menghadirkan keadilan, kejujuran, dan belas kasih Kristus dalam bidang politik, ekonomi, kebudayaan, dan profesi harian', 'Menjual barang-barang rohani di pasar', 'Menghindari berbicara tentang masalah sosial kemasyarakatan'], 1, 'Kaum awam dipanggil menguduskan tata dunia temporal, menjadi ragi kebenaran dan keadilan Injil di tengah masyarakat majemuk.');
addQ(6, 'sulit', 'Kuasa Mengikat dan Melepaskan Petrus', 'Yesus bersabda kepada Petrus: "Kepadamu akan Kuberikan kunci Kerajaan Surga. Apa yang kauikat di dunia ini akan terikat di surga dan apa yang kaulepaskan di dunia ini akan terlepas di surga" (Matius 16:19). Makna wewenang "mengikat dan melepaskan" ini adalah ...', ['Kuasa untuk memenjarakan musuh-musuh politik gereja', 'Wewenang penggembalaan tertinggi untuk memimpin, mengajarkan doktrin iman yang benar, menetapkan disiplin gerejawi, dan menerimakan pengampunan dosa', 'Kuasa untuk mencabut nyawa orang lain', 'Hak monopoli kunci pintu gerbang kota Yerusalem'], 1, 'Kuasa kunci melambangkan wewenang doktrinal, yurisdiksi penggembalaan, dan kuasa pengampunan sakramental dalam memimpin jemaat.');
addQ(6, 'sulit', 'Doktrin Infallibilitas Pengajaran Paus', 'Konsili Vatikan I menetapkan dogma "Infallibilitas Paus" (ketidaksalahan paus). Syarat ketat agar pernyataan Paus bersifat infallibel adalah saat Paus berbicara ...', ['Sebagai pribadi saat diwawancarai wartawan di pesawat terbang', 'Secara "Ex Cathedra" (dari takhta rasuli) sebagai gembala tertinggi Gereja semesta, secara eksplisit menetapkan ajaran mengenai iman atau moral (de fide et moribus) yang mengikat seluruh umat', 'Dalam surat ucapan selamat ulang tahun kepada presiden', 'Saat memimpin doa malaikat tuhan hari Minggu'], 1, 'Infallibilitas bukan berarti Paus tanpa dosa, melainkan karisma perlindungan Roh Kudus saat secara resmi (ex cathedra) menetapkan doktrin iman dan moral yang definitif.');
addQ(6, 'sulit', 'Etika Perkembangan AI dan Martabat Manusia', 'Vatikan mengeluarkan seruan "Rome Call for AI Ethics" menghadapi era kecerdasan buatan (Artificial Intelligence). Prinsip kristiani tertinggi yang wajib dijaga dalam pengembangan AI adalah ...', ['AI harus menggantikan seluruh pekerjaan guru dan pastor', 'Teknologi AI harus selalu ditempatkan melayani martabat luhur manusia, menjunjung keadilan, tidak memanipulasi kebenaran, dan melindungi hak-hak kaum lemah', 'AI boleh digunakan untuk memproduksi senjata perang pemusnah', 'Menolak sama sekali penggunaan komputer di sekolah'], 1, 'Etika teknologi katolik menempatkan kemajuan sains dan AI di bawah pelayanan martabat manusia (human-centered), bukan mendewakan algoritma.');
addQ(6, 'sulit', 'Panggilan Kenabian Ensiklik Rerum Novarum', 'Ensiklik sosial pertama Paus Leo XIII "Rerum Novarum" (1891) membela hak-hak buruh pabrik di era revolusi industri dengan menegaskan bahwa ...', ['Buruh adalah mesin produksi yang boleh dieksploitasi 24 jam', 'Majikan wajib memberikan upah yang adil dan layak bagi kehidupan keluarga buruh serta menghormati hak istirahat dan keselamatan kerja mereka', 'Gereja melarang pembentukan serikat buruh', 'Hanya kaum bangsawan yang berhak memiliki tanah'], 1, 'Rerum Novarum adalah tonggak ajaran sosial Gereja yang membela keadilan upah buruh dan menolak eksploitasi manusia sebagai komoditas.');
addQ(6, 'sulit', 'Makna Kebangkitan Badan Resurrectio Carnis', 'Dalam Syahadat iman kita mengikrarkan percaya akan "Kebangkitan Badan" (Resurrectio Carnis). Arti kebangkitan badan pada akhir zaman adalah ...', ['Roh manusia gentayangan mencari tubuh yang baru', 'Pada kedatangan Kristus kembali, tubuh jasmani manusia akan dibangkitkan dan dipersatukan kembali dengan jiwanya dalam kondisi mulia, abadi, dan terbebas dari kelemahan fana laksana tubuh kebangkitan Kristus', 'Tulang belulang manusia dihidupkan menjadi fosil museum', 'Hanya jiwa saja yang hidup selamanya tanpa tubuh'], 1, 'Keselamatan kristiani mencakup manusia seutuhnya (jiwa dan raga); tubuh yang fana akan diubah menjadi tubuh rohani yang mulia.');
addQ(6, 'sulit', 'Analisis Teologis Sifat Gereja Satu di Tengah Perpecahan', 'Gereja Katolik mengakui adanya luka perpecahan sejarah di antara orang-orang kristiani (munculnya Gereja Ortodoks dan Protestan). Sikap Gereja Katolik melalui gerakan Ekumenisme adalah ...', ['Memusuhi dan menganggap saudara non-katolik sebagai musuh iman', 'Mengakui adanya unsur-unsur kekudusan dan kebenaran pada saudara-saudara terpisah, serta terus berdoa dan berdialog dalam kasih menuju pemulihan kesatuan jemaat seturut doa Yesus (Ut Unum Sint)', 'Menuntut semua gereja lain membayar denda ganti rugi', 'Menolak berdoa bersama dalam persekutuan doa'], 1, 'Gerakan Ekumenisme digerakkan Roh Kudus memulihkan kesatuan seluruh murid Kristus sesuai doa Yesus: "Semoga mereka semua menjadi satu" (Yohanes 17:21).');
addQ(6, 'sulit', 'Tantangan Menghadapi Paham Sekularisme Radikal', 'Bagaimana seorang siswa kelas 6 katolik mempertahankan imannya di tengah masyarakat yang membuang nilai-nilai Tuhan dari ruang publik (sekularisme radikal)?', ['Menjadi fanatik kasar yang memaksakan aturan agama di ruang umum', 'Menghidupi imannya secara autentik dan cerdas, menjadi teladan kejujuran dan kasih tanpa rasa malu, serta menyuarakan kebaikan moral di tengah masyarakat', 'Mengundurkan diri dari pergaulan sosial sekolah', 'Mengabaikan seluruh ajaran moral Alkitab'], 1, 'Menghadapi sekularisme radikal dengan kesaksian hidup yang berintegritas, cerdas, berbelas kasih, dan menjadi garam peradaban.');
addQ(6, 'sulit', 'Makna Teologis Keperawanan Maria Abadi', 'Gereja Katolik mengimani dogma Bunda Maria "Tetap Perawan" (Semper Virgo). Makna rohani penyerahan diri Maria seutuhnya dalam keperawanan adalah ...', ['Maria tidak menyukai perkawinan keluarga', 'Penyerahan diri Maria yang total dan tanpa terbagi seumur hidup semata-mata demi karya keselamatan Allah dan pelayanan bagi Kristus Putranya', 'Hanya peraturan tradisi para rabi Nazaret', 'Maria takut melahirkan banyak anak'], 1, 'Keperawanan abadi Maria melambangkan kemurnian iman dan penyerahan diri yang utuh tanpa syarat kepada rencana keselamatan Ilahi.');
addQ(6, 'sulit', 'Etika Menjaga Kerahasiaan Rekan Sebaya', 'Bila seorang teman sekelas mencurahkan masalah keluarga atau kesedihannya secara pribadi kepada kita, kewajiban etika kristiani kita adalah ...', ['Menjadikan curahan hati kawan sebagai bahan cerita lucu di kantin', 'Menjaga amanah rahasia kawan dengan setia, mendampinginya dengan doa, dan membantunya mencari pertolongan guru BP jika menyangkut bahaya keselamatan', 'Mengunggah tangkapan layar curhat kawan ke media sosial', 'Menjual informasi rahasia itu kepada teman lain'], 1, 'Menjaga rahasia pribadi sesama adalah bagian dari kebajikan kesetiaan dan keadilan moral melindungi sesama.');
addQ(6, 'sulit', 'Makna Peringatan Orang Kudus Martir Abad Modern', 'Paus Fransiskus menegaskan bahwa pada abad ke-20 dan ke-21 ada lebih banyak martir kristiani yang gugur dibunuh karena membela iman dan keadilan dibanding abad-abad perdana. Pelajaran bagi generasi muda adalah ...', ['Menghindari pergi ke tempat ibadah gereja', 'Menyadari bahwa kemuridan kristiani menuntut keteguhan iman yang mahal (costly grace) dan keberanian membela martabat kemanusiaan di tengah bahaya penganiayaan', 'Membalas dendam dengan membentuk pasukan militer rahasia', 'Melupakan sejarah masa lampau'], 1, 'Kemartiran modern membuktikan bahwa kuasa Injil tetap hidup dan menuntut keberanian bersaksi bagi kebenaran di tengah tantangan zaman.');
addQ(6, 'sulit', 'Analisis Doa Penyerahan Santa Faustina Kerahiman Ilahi', 'Santa Faustina Kowalska menerima wahyu devosi Kerahiman Ilahi dengan semboyan: "Yesus, Engkau Andalanku" (Jezu, ufam Tobie). Nilai spiritual terdalam dari penyerahan ini adalah ...', ['Kita tidak perlu lagi belajar karena sudah pasrah total', 'Menaruh kepercayaan (trust) tanpa syarat kepada maharahim cinta Allah yang melampaui segala kerapuhan dan kelemahan dosa manusia', 'Percaya bahwa kita akan langsung menjadi kaya raya', 'Menolak meminum obat saat sakit'], 1, 'Devosi Kerahiman Ilahi berpusat pada penyerahan iman yang teguh kepada kerahiman Kristus yang tak bertepi.');
addQ(6, 'sulit', 'Kearifan Menghadapi Kekecewaan dalam Doa', 'Ketika doa permohonan kita belum dikabulkan oleh Tuhan seperti yang kita inginkan, sikap kedewasaan iman kristiani yang diajarkan Gereja adalah ...', ['Marah kepada Tuhan dan mogok tidak mau Misa', 'Percaya bahwa Allah selalu memberikan apa yang kita butuhkan pada waktu yang tepat seturut rancangan terbaik-Nya, bukan sekadar apa yang kita inginkan sesaat', 'Mencari dukun atau paranormal untuk memaksakan keinginan', 'Mengutuk takdir hidup'], 1, 'Kedewasaan iman mempercayai hikmat dan waktu Allah (kairos): doa mendidik kehendak manusia selaras dengan kehendak Ilahi.');
addQ(6, 'sulit', 'Pemberian Berkat Lewat Pengampunan Musuh Politik', 'Dalam sejarah, Santo Yohanes Paulus II secara terbuka mengampuni rezim komunis yang pernah menindas Gereja di Polandia. Kebijaksanaan ini membuktikan bahwa ...', ['Gereja takut pada ancaman senjata perang', 'Kekuatan kebenaran moral dan pengampunan kasih tanpa kekerasan lebih ampuh meruntuhkan tirani kekuasaan diktator dibanding kekuatan senjata militer', 'Paus ingin mendapatkan pujian di surat kabar internasional', 'Hanya taktik politik praktis sesaat'], 1, 'Revolusi damai tanpa kekerasan yang berlandaskan kebenaran moral dan kasih Kristus terbukti sanggup menumbangkan tirani penindasan.');
addQ(6, 'sulit', 'Tantangan Menghadapi Tekanan Hedonisme Remaja', 'Bagaimana seorang murid kelas 6 katolik mengamalkan kebajikan keugaharian (temperantia) menghadapi godaan tren pamer kekayaan (flexing) di media sosial?', ['Memaksa orang tua membelikan barang bermerek mahal agar bisa ikut pamer di Instagram', 'Menemukan kebahagiaan sejati dalam rasa syukur atas apa yang ada, hidup bersahaja, tidak menilai orang dari kemewahan materi, dan memperkaya kecantikan batiniah kebajikan', 'Menghina teman yang tidak memakai sepatu mahal', 'Menghapus seluruh akun media sosial'], 1, 'Kebajikan keugaharian (temperantia) membebaskan manusia dari perbudakan pamer materi menuju kematangan karakter batin.');
addQ(6, 'sulit', 'Makna "Marilah Kita Menjadi Duta Kristus"', '2 Korintus 5:20 menyatakan: "Jadi kami ini adalah utusan-utusan (duta-duta) Kristus, seakan-akan Allah menasihati kamu dengan perantaraan kami...". Gelar duta Kristus bagi seorang lulusan SD katolik menuntut tanggung jawab untuk ...', ['Membawa paspor diplomatik ke mana pun pergi', 'Mencerminkan karakter, keadilan, kasih, dan kejujuran Kristus dalam seluruh tutur kata dan perbuatan saat melangkah ke jenjang sekolah yang lebih tinggi', 'Memerintah murid-murid lain dengan suara keras', 'Menolak mematuhi tata tertib sekolah baru'], 1, 'Duta Kristus adalah perwakilan sejati: hidupnya menjadi surat Kristus yang terbuka, memancarkan kasih dan kebenaran Allah bagi dunia.');

addQ(6, 'sulit', 'Fides et Ratio Iman dan Akal Budi', 'Dalam ensiklik "Fides et Ratio", Santo Paus Yohanes Paulus II melukiskan bahwa Iman dan Akal Budi bagaikan dua sayap yang memampukan budi manusia terbang menuju ...', ['Kekuasaan teknologi senjata militer', 'Kontemplasi kebenaran sejati yang berpuncak pada Allah', 'Kekayaan tambang emas di bumi', 'Ketenaran bintang film'], 1, 'Iman dan akal budi tidak bertentangan; keduanya saling melengkapi memandu manusia mengenal kebenaran sejati Allah.');
addQ(6, 'sulit', 'Prinsip Subsidiaritas Ajaran Sosial Gereja', 'Prinsip "Subsidiaritas" dalam Ajaran Sosial Gereja Katolik menegaskan bahwa wewenang pengambilan keputusan kemasyarakatan ...', ['Harus selalu dipusatkan kepada pemerintah pusat di ibu kota', 'Tidak boleh dirampas oleh tingkatan yang lebih tinggi jika perkara tersebut dapat diselesaikan secara efektif dan bijaksana oleh komunitas keluarga atau tingkatan lokal', 'Hanya diserahkan kepada para pengusaha konglomerat', 'Harus diundi melalui undian lotre'], 1, 'Subsidiaritas melindungi prakarsa, kebebasan, dan martabat komunitas lokal dari pemaksaan kekuasaan pusat yang berlebihan.');
addQ(6, 'sulit', 'Prinsip Solidaritas Bonum Commune', 'Prinsip "Solidaritas" dalam ajaran katolik menuntut tekad moral yang kokoh dan gigih untuk membaktikan diri demi ...', ['Keuntungan finansial golongan sendiri semata', 'Kebaikan bersama (Bonum Commune), karena kita semua bertanggung jawab atas semua sesama manusia', 'Kemenangan partai politik tertentu', 'Popularitas pribadi di dunia maya'], 1, 'Solidaritas adalah komitmen moral memperjuangkan kebaikan bersama (bonum commune) karena semua manusia bersaudara.');
addQ(6, 'sulit', 'Konsep Bonum Commune Kesejahteraan Bersama', 'Apakah yang dimaksud dengan "Bonum Commune" (Kesejahteraan Bersama) dalam Katekismus Gereja Katolik?', ['Jumlah tabungan uang kas negara yang tersimpan di brankas bank', 'Keseluruhan syarat-syarat hidup kemasyarakatan yang memungkinkan manusia (baik perorangan maupun kelompok) mencapai kepenuhan martabat dan kesempurnaan hidupnya secara lebih utuh dan mudah', 'Pembagian makanan gratis setiap akhir pekan', 'Sistem bagi hasil keuntungan perusahaan swasta'], 1, 'Bonum commune mencakup perlindungan hak asasi, pemenuhan kebutuhan dasar, dan tatanan damai yang adil bagi seluruh warga.');
addQ(6, 'sulit', 'Konsili Vatikan II Dekrit Unitatis Redintegratio', 'Dekrit Konsili Vatikan II tentang Ekumenisme "Unitatis Redintegratio" mengajarkan bahwa pemulihan kesatuan jemaat kristiani harus berawal dari ...', ['Penyerahan seluruh gedung gereja lain ke Roma', 'Pertobatan hati, pembaruan hidup batin, kesucian hidup, serta doa permohonan bersama yang tekun', 'Perdebatan teologi panas di televisi', 'Pembayaran ganti rugi sejarah'], 1, 'Ekumenisme spiritual (pertobatan hati dan doa bersama) adalah jiwa dari seluruh gerakan pemulihan kesatuan kristiani.');
addQ(6, 'sulit', 'Dogma Maria Diangkat ke Surga Assumptio', 'Paus Pius XII pada tahun 1950 menetapkan dogma "Assumptio Mariae" (Maria Diangkat ke Surga). Arti dari dogma iman ini adalah bahwa Bunda Maria ...', ['Terbang menggunakan sayap malaikat perak', 'Setelah menyelesaikan perjalanan hidupnya di bumi, diangkat jiwa dan raganya ke dalam kemuliaan surgawi oleh kuasa Allah sebagai buah pertama penebusan Kristus', 'Dimakamkan di bawah altar basilika Roma', 'Menjadi penguasa bintang-bintang di angkasa'], 1, 'Assumptio Mariae menyatakan Maria dimuliakan seutuhnya (tubuh dan jiwa) di surga, menjadi tanda pengharapan eskatologis kebangkitan kita.');
addQ(6, 'sulit', 'Tolok Ukur Penghakiman Terakhir Matius 25', 'Dalam perumpamaan Penghakiman Terakhir (Matius 25:31-46), Kristus Sang Raja memisahkan domba dan kambing berdasarkan tolok ukur ...', ['Seberapa banyak sertifikat kejuaraan yang kita miliki', 'Sejauh mana kita memberi makan orang yang lapar, memberi minum yang haus, menyambut orang asing, memberi pakaian yang telanjang, serta melawat orang sakit dan dipenjara', 'Seberapa sering kita mengkritik orang lain di media sosial', 'Tingginya jabatan kedudukan sosial kita di masyarakat'], 1, 'Tolok ukur pengadilan kekal Kristus adalah kasih konkret kepada kaum yang paling hina dan menderita (Matius 25:40).');
addQ(6, 'sulit', 'Ensiklik Caritas in Veritate Kasih dalam Kebenaran', 'Paus Benediktus XVI dalam ensiklik "Caritas in Veritate" menegaskan bahwa kasih tanpa kebenaran akan merosot menjadi ...', ['Kekuatan yang tak terkalahkan', 'Sentimentalitas emosional yang dangkal dan mudah dimanipulasi kepentingan egois kekuasaan', 'Hukum pidana yang kaku', 'Kemenangan mutlak di pengadilan'], 1, 'Kasih membutuhkan terang kebenaran akal budi dan iman agar tidak menjadi sentimentalitas hampa yang menyesatkan.');
addQ(6, 'sulit', 'Veritatis Splendor Kebebasan dan Hati Nurani', 'Ensiklik Paus Yohanes Paulus II "Veritatis Splendor" (Cahaya Kebenaran) mengajarkan bahwa kebebasan sejati manusia bukanlah kebebasan berbuat sesuka hati, melainkan ...', ['Kebebasan untuk melanggar aturan saat sepi', 'Kebebasan memilih dan melakukan apa yang benar dan baik seturut hukum moral Allah yang tertulis di dalam hati nurani', 'Ketiadaan seluruh undang-undang hukum di negara', 'Kekuasaan untuk menindas orang yang lebih lemah'], 1, 'Kebebasan manusia berakar pada kebenaran; kebebasan sejati menuntun manusia memilih kebaikan dan ketaatan kepada Allah.');
addQ(6, 'sulit', 'Makna "Sudah Selesai" Consummatum Est di Salib', 'Sebelum menghembuskan nafas terakhir di kayu salib, Yesus berseru: "Sudah selesai!" (Consummatum est / Tetelestai). Seruan agung ini bermakna ...', ['Yesus menyerah kalah pada kekejaman tentara Romawi', 'Karya kurban penebusan dosa manusia telah tuntas digenapi secara sempurna seturut rencana keselamatan Allah Bapa', 'Waktu perjamuan makan Paskah telah berakhir', 'Yesus meminta para murid membubarkan diri'], 1, 'Consummatum est adalah pekik kemenangan penebusan: hutang dosa manusia telah lunas dibayar oleh kurban cinta kasih Kristus.');

